cd ~/skills/clawshield-lite && cat > main.py << 'EOF'
#!/usr/bin/env python3
"""
ClawShield Lite - a lightweight security analysis skill that scans AI skill
code for risky patterns and outputs a structured JSON risk report.

Usage:
    echo "<code>" | python main.py
    python main.py < some_file.py
"""

import sys
import os
import re
import json


def load_rules():
    rules_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rules.json")
    with open(rules_path, "r") as f:
        return json.load(f)


def scan(code, rules):
    findings = {
        "dangerous": [],
        "suspicious": []
    }

    for category, key in (("dangerous_patterns", "dangerous"), ("suspicious_patterns", "suspicious")):
        for rule in rules.get(category, []):
            pattern = rule["pattern"]
            description = rule.get("description", "")
            matches = list(re.finditer(pattern, code, re.IGNORECASE))
            if matches:
                findings[key].append({
                    "pattern": pattern,
                    "description": description,
                    "matches": [m.group(0) for m in matches],
                    "count": len(matches)
                })

    return findings


def assign_risk_level(findings):
    if findings["dangerous"]:
        return "HIGH RISK"
    if findings["suspicious"]:
        return "MEDIUM RISK"
    return "SAFE"


def main():
    code = sys.stdin.read()

    rules = load_rules()
    findings = scan(code, rules)
    risk_level = assign_risk_level(findings)

    report = {
        "risk_level": risk_level,
        "dangerous_findings": findings["dangerous"],
        "suspicious_findings": findings["suspicious"],
        "summary": {
            "dangerous_count": len(findings["dangerous"]),
            "suspicious_count": len(findings["suspicious"])
        }
    }

    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
EOF
